const HINT = 'Topshiriqdagi so‘z yoki qolip gapda topilmadi.';
const UP_PROMPT: Record<string, string> = {
  although: 'Ikki sodda gapni “although” bilan bitta gapga birlashtiring.',
  because: 'Ikki sodda gapni “because” bilan bitta gapga birlashtiring.',
  which: 'Ikki gapni “which” bilan bitta gapga birlashtiring.',
  who: 'Ikki gapni “who” bilan bitta gapga birlashtiring.',
  whereas: "'whereas' yoki 'while' bilan bitta gap qilib yozing.",
  'so that': 'Ikki gapni “so that” bilan birlashtirib, maqsadni bildiring.',
  when: 'Ikki gapni “when” bilan bitta gapga birlashtiring.',
  if: 'Ikki gapni “if” bilan shart gap qilib qayta yozing.',
  ing: 'Birinchi harakatni -ing shaklidagi qism bilan boshlab, ikki gapni birlashtiring.',
  despite: 'Gapni “despite” bilan qayta yozing.',
  'not only': 'Ikki gapni “not only … but also” bilan birlashtiring.',
  passive: 'Gapni majhul nisbatda qayta yozing.',
  word: 'Gapdagi oddiy so‘zni kuchliroq, aniqroq so‘z bilan almashtiring.',
};
const usePrompt = (label: string): string => (/[\s+…/]/.test(label) ? `“${label}” qolipi bilan gap tuzing.` : `“${label}” so‘zi bilan gap tuzing.`);
const opt = <K extends string, V>(k: K, v: V[] | undefined): { [P in K]?: V[] } => (v && v.length ? ({ [k]: v } as { [P in K]?: V[] }) : {});

export const bankExercises: Exercise[] = [
  ...FIX_ROWS.map(([level, topic, shown, model, explainUz, accept], i): Exercise => ({ id: `fx${i + 1}`, level, kind: 'fix', topic, promptUz: FIXP, shown, model, ...opt('accept', accept), explainUz })),
  ...TR_ROWS.map(([level, topic, promptUz, model, explainUz, accept], i): Exercise => ({ id: `tx${i + 1}`, level, kind: 'translate', topic, promptUz, model, ...opt('accept', accept), explainUz })),
  ...BD_ROWS.map(([level, topic, promptUz, model, explainUz, accept, extra], i): Exercise => ({ id: `bx${i + 1}`, level, kind: 'build', topic, promptUz, model, ...opt('accept', accept), ...opt('extra', extra), explainUz })),
  ...USE_ROWS.map(([level, topic, label, re, model, minWords, explainUz], i): Exercise => ({ id: `ux${i + 1}`, level, kind: 'use', topic, promptUz: usePrompt(label), must: [{ re, hintUz: HINT }], minWords, model, explainUz })),
  ...UPGRADE_ROWS.map(([level, topic, key, shown, re, model, explainUz], i): Exercise => ({ id: `gx${i + 1}`, level, kind: 'upgrade', topic, promptUz: UP_PROMPT[key]!, shown, must: [{ re, hintUz: HINT }], model, explainUz })),
];
